                split = False
                ast.xy = x, y
                w, h = 16, 28
                if x >= 160-16:
                    w -= (x+16)-160
                    split = True
                if y >= 194-28:
                    h -= (y+28)-194
                    split = True
                if w < 0 or h < 0:
                    ast = None
                else:
                    ast.wh = w, h
                if split and 16-w > 0 and 28-h > 0:
                    ast2 = Asteroid()
                    objects[16+i] = ast2
                    if w == 16:
                        ast2.xy = x, 18
                        ast2.wh = 16, 28-h
                    elif h == 28:
                        ast2.xy = 0, y
                        ast2.wh = 16-w, 28
                    else:
                        ast2.xy = 0, 18
                        ast2.wh = 16-w, 28-h
                else:
                    objects[16+i] = None

            elif ram_state[ast_list[i]+36]&127 < 48:
                split = False
                ast.xy = x-1, y-2
                w, h = 8, 15
                if x >= 160-8:
                    w -= (x+7)-160
                    split = True
                if y >= 194-15:
                    h -= (y+13)-194
                    split = True
                if w < 0 or h < 0:
                    ast = None
                else:
                    ast.wh = w, h
                if split and 8-w > 0 and 15-h > 0:
                    ast2 = Asteroid()
                    objects[16+i] = ast2
                    if w == 8:
                        ast2.xy = x-1, 18
                        ast2.wh = 8, 15-h
                    elif h == 15:
                        ast2.xy = 0, y-2
                        ast2.wh = 8-w, 15
                    else:
                        ast2.xy = 0, 18
                        ast2.wh = 8-w, 15-h
                else:
                    objects[16+i] = None
            else:
                split = False
                ast.xy = x-1, y-1
                w, h = 4, 8
                if x >= 160-4:
                    w -= (x+3)-160
                    split = True
                if y >= 194-8:
                    h -= (y+7)-194
                    split = True
                if w < 0 or h < 0:
                    ast = None
                else:
                    ast.wh = w, h
                if split and 4-w > 0 and 8-h > 0:
                    ast2 = Asteroid()
                    objects[16+i] = ast2
                    if w == 4:
                        ast2.xy = x-1, 18
                        ast2.wh = 4, 15-h
                    elif h == 8:
                        ast2.xy = 0, y-1
                        ast2.wh = 8-w, 8
                    else:
                        ast2.xy = 0, 18
                        ast2.wh = 4-w, 8-h
                else:
                    objects[16+i] = None
            if ast is not None:
                w1, h1 = ast.wh
                if w1 < 0:
                    print(w1, "wtf w1?")
                if h1 < 0:
                    print(h1, "wtf h1?")
            if ast2 is not None:
                w2, h2 = ast2.wh
                if w2 < 0:
                    print(w2, "wtf w2?")
                if h2 < 0:
                    print(h2, "wtf h2?")
        else:
            objects[1+i] = None
            objects[16+i] = None

    if ram_state[83] and not ram_state[86]&128:
        miss = PlayerMissile()
        objects[16] = miss
        miss.xy = _x_position(ram_state[83]) + 1, 175 - 2 * (80 - ram_state[86]) + 2
    else:
        objects[16] = None


    if ram_state[84] and not ram_state[87]&128:
        miss = PlayerMissile()
        objects[17] = miss
        miss.xy = _x_position(ram_state[84]) + 1, 175 - 2 * (80 - ram_state[87]) + 2
    else:
        objects[17] = None

    if hud:
        if ram_state[61] >= 16:
            score = PlayerScore()
            objects[-1] = score
            score.xy = 4, 5
            score.wh = 76, 10
        elif ram_state[61]:
            score = PlayerScore()
            objects[-1] = score
            score.xy = 20, 5
            score.wh = 60, 10
        elif ram_state[62] >= 16:
            score = PlayerScore()
            objects[-1] = score
            score.xy = 36, 5
            score.wh = 44, 10
        elif ram_state[62]:
            score = PlayerScore()
            objects[-1] = score
            score.xy = 52, 5
            score.wh = 28, 10
        else:
            score = PlayerScore()
            objects[-1] = score
            score.xy = 68, 5
            score.wh = 12, 10



def _x_position(value):
    ls = value&15
    add = 8*((value>>7)&1)
    sub = (value>>4)&7
    if value == 0:
        return 64
    elif value == 1:
        return 4
    elif ls%2 == 0:
        mult = (ls/2)-1
        return 97 + 15 * mult + add - sub
    elif ls%2 == 1:
        mult = ((ls-1)/2)-1
        return 10 + 15 * mult + add - sub

